export const FABRICS={custom:{label:'Personalizado'},flat:{label:'Tecido plano',spacing:.42,pull:.1},knit:{label:'Malha / polo',spacing:.45,pull:.2},towel:{label:'Toalha',spacing:.48,pull:.25}};
export function applyFabric(object,id){const p=FABRICS[id];if(!p||object.kind==='machine')return false;object.fabric=id;if(id!=='custom'){object.spacing=p.spacing;object.pull=p.pull;object.underlay=true;if(object.kind==='satin'&&object.artworkContours?.length&&object.paths.some(path=>(path.width||object.width||1.2)+2*p.pull>6)){object.satinPaths=JSON.parse(JSON.stringify(object.paths));object.kind='fill';object.paths=JSON.parse(JSON.stringify(object.artworkContours));object.clipToArtwork=false;object.analysis={...object.analysis,method:'fill',coverage:null,reason:'Coluna larga para a compensação deste perfil: preenchimento aplicado.'};}}return true;}
export function setRegionKind(object,kind){if(object.kind==='machine')return false;if(object.artworkContours?.length){if(object.kind==='satin'||object.kind==='running')object.satinPaths=JSON.parse(JSON.stringify(object.paths));if(kind==='fill'){object.paths=JSON.parse(JSON.stringify(object.artworkContours));object.clipToArtwork=false;}else if(object.satinPaths?.length){object.paths=JSON.parse(JSON.stringify(object.satinPaths));object.clipToArtwork=kind==='satin';}else if(kind==='running'){object.paths=JSON.parse(JSON.stringify(object.artworkContours));for(const path of object.paths)path.points.push({...path.points[0]});object.clipToArtwork=false;}else throw Error('Esta região não tem coluna confiável. Trace o satin manualmente usando o contorno como referência.');}object.kind=kind;return true;}
export function resizeRegion(object,fx,fy){if(object.kind==='machine')throw Error('A matriz importada não contém objetos para recalcular densidade.');const seen=new Set(),widthFactor=Math.max(fx,fy);for(const paths of [object.paths,object.artworkContours,object.satinPaths])for(const path of paths||[]){if(seen.has(path))continue;seen.add(path);for(const p of path.points){p.x*=fx;p.y*=fy}if(path.width)path.width*=widthFactor;if(path.widths)path.widths=path.widths.map(w=>w*widthFactor);}object.width=(object.width||1.2)*widthFactor;if(object.analysis){object.analysis.coverage=null;object.analysis.reason='Região redimensionada: confira a cobertura e os detalhes na nova escala.';}if(object.kind==='satin'&&object.artworkContours?.length&&object.paths.some(path=>(path.width||object.width)+2*(object.pull||0)>6))setRegionKind(object,'fill');}
export function designSignature(doc){const objects=doc.objects.filter(o=>o.visible!==false&&!o.reference).map(o=>({kind:o.kind,x:o.x||0,y:o.y||0,color:o.color,colors:o.colors,commands:o.commands,paths:o.paths?.map(p=>({points:p.points,width:p.width,widths:p.widths,fixedEntry:p.fixedEntry})),contours:o.clipToArtwork?o.artworkContours?.map(p=>p.points):null,clip:!!o.clipToArtwork,width:o.width,spacing:o.spacing,length:o.length,angle:o.angle,underlay:o.underlay,pull:o.pull,startAtFirst:o.startAtFirst,lockOrder:o.lockOrder}));const raw=JSON.stringify({objects,trim:doc.trim,optimize:doc.optimize,smartTravel:doc.smartTravel,concealedTravel:doc.concealedTravel});let hash=2166136261;for(let i=0;i<raw.length;i++){hash^=raw.charCodeAt(i);hash=Math.imul(hash,16777619)}return (hash>>>0).toString(16);}
